using Mbb.Archive.Modules.Archive.Application;
using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.BuildingBlocks.Domain;using Mbb.Archive.Modules.Archive.Application.Abstractions;using Mbb.Archive.Modules.Archive.Contracts.IntegrationEvents;using Mbb.Archive.Modules.Archive.Domain.Records;
namespace Mbb.Archive.Modules.Archive.Application.Records.Declare;
public sealed class DeclareArchiveRecordCommandHandler:ICommandHandler<DeclareArchiveRecordCommand>{private readonly IArchiveRecordRepository _records;private readonly IOutbox<ArchiveBoundary> _outbox;private readonly IUnitOfWork<ArchiveBoundary> _uow;private readonly TimeProvider _time;public DeclareArchiveRecordCommandHandler(IArchiveRecordRepository records,IOutbox<ArchiveBoundary> outbox,IUnitOfWork<ArchiveBoundary> uow,TimeProvider time){_records=records;_outbox=outbox;_uow=uow;_time=time;}public async Task<Result> Handle(DeclareArchiveRecordCommand command,CancellationToken ct){var record=await _records.GetAsync(new ArchiveRecordId(command.RecordId),ct);if(record is null)return Result.Failure(Error.NotFound("archive.record_not_found","Archive record was not found."));try{var now=_time.GetUtcNow();record.Declare(command.ClassificationCode,command.RetentionRuleCode,now);_outbox.Enqueue(new ArchiveRecordDeclaredIntegrationEvent(Guid.CreateVersion7(),record.Id.Value,record.DocumentId,record.DocumentVersionId,record.ClassificationCode!,record.RetentionRuleCode!,record.OriginalStorageKey,record.Sha256Hash,now,now));await _uow.SaveChangesAsync(ct);return Result.Success();}catch(DomainRuleViolationException ex){return Result.Failure(Error.Conflict("archive.declaration_conflict",ex.Message));}}}
